import{_ as t,c as a,o as d,ae as r}from"./chunks/framework.DCU7Csu6.js";const u=JSON.parse('{"title":"EPIC 41: Analytics Type & Schema Fixes — AvailabilityFilters bug, TableProductItem, missing schemas","description":"","frontmatter":{},"headers":[],"relativePath":"epics/EPIC_41_ANALYTICS_TYPE_SCHEMA_FIXES.md","filePath":"epics/EPIC_41_ANALYTICS_TYPE_SCHEMA_FIXES.md"}'),o={name:"epics/EPIC_41_ANALYTICS_TYPE_SCHEMA_FIXES.md"};function i(s,e,n,c,l,p){return d(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="epic-41-analytics-type-schema-fixes-—-availabilityfilters-bug-tableproductitem-missing-schemas" tabindex="-1">EPIC 41: Analytics Type &amp; Schema Fixes — AvailabilityFilters bug, TableProductItem, missing schemas <a class="header-anchor" href="#epic-41-analytics-type-schema-fixes-—-availabilityfilters-bug-tableproductitem-missing-schemas" aria-label="Permalink to &quot;EPIC 41: Analytics Type &amp; Schema Fixes — AvailabilityFilters bug, TableProductItem, missing schemas&quot;">​</a></h1><hr><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td><strong>Epic</strong></td><td>41</td></tr><tr><td><strong>Module</strong></td><td>analytics (<code>11-analytics.yaml</code>)</td></tr><tr><td><strong>Priority</strong></td><td>High</td></tr><tr><td><strong>Target SDK Version</strong></td><td>v2.7.x</td></tr><tr><td><strong>Backlog Task</strong></td><td>task-41</td></tr><tr><td><strong>Depends On</strong></td><td>None (standalone type fixes)</td></tr><tr><td><strong>Source</strong></td><td>February 2026 Swagger Audit</td></tr><tr><td><strong>Related Stories</strong></td><td>3.3 (Analytics Sales Statistics), 3.4 (Analytics Stock CSV Reports), 4.3 (Analytics Sales Statistics)</td></tr></tbody></table><hr><h2 id="current-state" tabindex="-1">Current State <a class="header-anchor" href="#current-state" aria-label="Permalink to &quot;Current State&quot;">​</a></h2><h3 id="what-exists" tabindex="-1">What Exists <a class="header-anchor" href="#what-exists" aria-label="Permalink to &quot;What Exists&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Asset</th><th>Path</th><th>Details</th></tr></thead><tbody><tr><td>Module implementation</td><td><code>src/modules/analytics/index.ts</code></td><td>533 lines, 19 methods</td></tr><tr><td>Types file</td><td><code>src/types/analytics.types.ts</code></td><td>1901 lines, ~100 interfaces/types</td></tr><tr><td>Rate limits</td><td><code>src/config/analytics-rate-limits.ts</code></td><td>97 lines</td></tr><tr><td>Unit tests</td><td><code>tests/unit/modules/analytics-v3-methods.test.ts</code></td><td>659 lines</td></tr><tr><td>Swagger spec</td><td><code>wildberries_api_doc/11-analytics.yaml</code></td><td>92 schemas</td></tr><tr><td>Swagger shards</td><td><code>wildberries_api_doc/11-analytics/</code></td><td>4 shards (voronka-prodazh, poiskovye-zaprosy, istoriya-ostatkov, analitika-prodavtsa-csv)</td></tr><tr><td>Deprecated v2 spec</td><td><code>wildberries_api_doc/11-analytics.v2-deprecated.yaml</code></td><td>Legacy v2 endpoints</td></tr></tbody></table><h3 id="what-is-wrong" tabindex="-1">What Is Wrong <a class="header-anchor" href="#what-is-wrong" aria-label="Permalink to &quot;What Is Wrong&quot;">​</a></h3><p>Six issues have been identified in the analytics module types:</p><ol><li><p><strong>AvailabilityFilters union/array precedence bug (CRITICAL)</strong>: The current type is defined as <code>&#39;deficient&#39; | &#39;actual&#39; | &#39;balanced&#39; | &#39;nonActual&#39; | &#39;nonLiquid&#39; | &#39;invalidData&#39;[]</code>. Due to TypeScript operator precedence, only the last variant <code>&#39;invalidData&#39;</code> becomes an array — the type parses as <code>&#39;deficient&#39; | &#39;actual&#39; | &#39;balanced&#39; | &#39;nonActual&#39; | &#39;nonLiquid&#39; | &#39;invalidData&#39;[]</code> instead of an array of the union. The swagger defines this as <code>type: array, items: { type: string, enum: [...] }</code>, meaning the entire value should be an array of enum strings.</p></li><li><p><strong>TableProductItem is an empty interface (HIGH)</strong>: Currently defined as an empty interface with a comment &quot;API returns empty object&quot;. The swagger defines 18+ fields via an <code>allOf</code> structure including product identifiers, metrics, and visibility data. This means SDK consumers get no type safety for table product responses.</p></li><li><p><strong>Missing ErrorObject type (MEDIUM)</strong>: The v3 endpoints return error responses with <code>code</code> and <code>message</code> fields, but no <code>ErrorObject</code> type exists in the SDK to represent them.</p></li><li><p><strong>OrderByMainAndDetails schema not properly represented (MEDIUM)</strong>: The swagger defines an <code>OrderByMainAndDetails</code> schema, but the SDK uses a generic <code>OrderBy</code> name. This creates a mismatch between the swagger specification and SDK types.</p></li><li><p><strong>getDownloadsFile returns Promise&lt;unknown&gt; (MEDIUM)</strong>: The swagger specifies <code>application/zip</code> binary response for file downloads, but the method returns <code>Promise&lt;unknown&gt;</code> instead of <code>Promise&lt;ArrayBuffer&gt;</code> or an appropriate binary type.</p></li><li><p><strong>ResponseError orphan type (LOW)</strong>: A <code>ResponseError</code> type exists in the SDK that does not correspond to any swagger schema. It should be removed or documented with rationale.</p></li></ol><h3 id="why-this-matters" tabindex="-1">Why This Matters <a class="header-anchor" href="#why-this-matters" aria-label="Permalink to &quot;Why This Matters&quot;">​</a></h3><ul><li><strong>AvailabilityFilters silently accepts wrong data</strong>: The malformed union means TypeScript will accept a bare string <code>&#39;deficient&#39;</code> where an array is expected, causing runtime type mismatches with the API</li><li><strong>TableProductItem provides zero type safety</strong>: SDK consumers must cast or use <code>as any</code> to access the 18+ fields the API actually returns, defeating the purpose of a typed SDK</li><li><strong>Missing error types</strong>: v3 error responses cannot be properly typed or handled</li><li><strong>Binary download is untyped</strong>: File download consumers have no type guidance for handling the response</li><li><strong>6 deprecated v2 types must be preserved</strong>: Removing them would break existing consumers</li></ul><hr><h2 id="gap-analysis" tabindex="-1">Gap Analysis <a class="header-anchor" href="#gap-analysis" aria-label="Permalink to &quot;Gap Analysis&quot;">​</a></h2><h3 id="availabilityfilters-type-comparison" tabindex="-1">AvailabilityFilters Type Comparison <a class="header-anchor" href="#availabilityfilters-type-comparison" aria-label="Permalink to &quot;AvailabilityFilters Type Comparison&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Current (Malformed)</th><th>Correct (Per Swagger)</th></tr></thead><tbody><tr><td><code>&#39;deficient&#39; | &#39;actual&#39; | &#39;balanced&#39; | &#39;nonActual&#39; | &#39;nonLiquid&#39; | &#39;invalidData&#39;[]</code></td><td><code>(&#39;deficient&#39; | &#39;actual&#39; | &#39;balanced&#39; | &#39;nonActual&#39; | &#39;nonLiquid&#39; | &#39;invalidData&#39;)[]</code></td></tr><tr><td>Only <code>&#39;invalidData&#39;</code> is treated as array element</td><td>Entire union is the array element type</td></tr><tr><td>Accepts bare strings — wrong</td><td>Only accepts array of enum values — correct</td></tr></tbody></table><h3 id="tableproductitem-field-gap" tabindex="-1">TableProductItem Field Gap <a class="header-anchor" href="#tableproductitem-field-gap" aria-label="Permalink to &quot;TableProductItem Field Gap&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Source</th></tr></thead><tbody><tr><td><code>nmId</code></td><td><code>number</code></td><td>allOf structure in swagger</td></tr><tr><td><code>name</code></td><td><code>string</code></td><td>allOf structure in swagger</td></tr><tr><td><code>vendorCode</code></td><td><code>string</code></td><td>allOf structure in swagger</td></tr><tr><td><code>subjectName</code></td><td><code>string</code></td><td>allOf structure in swagger</td></tr><tr><td><code>brandName</code></td><td><code>string</code></td><td>allOf structure in swagger</td></tr><tr><td><code>mainPhoto</code></td><td><code>string</code></td><td>allOf structure in swagger</td></tr><tr><td><code>isAdvertised</code></td><td><code>boolean</code></td><td>allOf structure in swagger</td></tr><tr><td><code>isSubstitutedSKU</code></td><td><code>boolean</code></td><td>allOf structure in swagger</td></tr><tr><td><code>isCardRated</code></td><td><code>boolean</code></td><td>allOf structure in swagger</td></tr><tr><td><code>rating</code></td><td><code>number</code></td><td>allOf structure in swagger</td></tr><tr><td><code>feedbackRating</code></td><td><code>number</code></td><td>allOf structure in swagger</td></tr><tr><td><code>price</code></td><td><code>number</code></td><td>allOf structure in swagger</td></tr><tr><td><code>avgPosition</code></td><td><code>number</code></td><td>allOf structure in swagger</td></tr><tr><td><code>openCard</code></td><td><code>number</code></td><td>allOf structure in swagger</td></tr><tr><td><code>addToCart</code></td><td><code>number</code></td><td>allOf structure in swagger</td></tr><tr><td><code>openToCart</code></td><td><code>number</code></td><td>allOf structure in swagger</td></tr><tr><td><code>orders</code></td><td><code>number</code></td><td>allOf structure in swagger</td></tr><tr><td><code>cartToOrder</code></td><td><code>number</code></td><td>allOf structure in swagger</td></tr><tr><td><code>visibility</code></td><td><code>number</code></td><td>allOf structure in swagger</td></tr></tbody></table><h3 id="missing-types" tabindex="-1">Missing Types <a class="header-anchor" href="#missing-types" aria-label="Permalink to &quot;Missing Types&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Schema Name</th><th>Purpose</th><th>Used By</th></tr></thead><tbody><tr><td><code>ErrorObject</code></td><td>v3 error response with <code>code</code> and <code>message</code> fields</td><td>All v3 analytics endpoints</td></tr><tr><td><code>OrderByMainAndDetails</code></td><td>Sort order for main/details combined queries</td><td>Sales funnel v3 endpoints</td></tr></tbody></table><h3 id="method-signature-issues" tabindex="-1">Method Signature Issues <a class="header-anchor" href="#method-signature-issues" aria-label="Permalink to &quot;Method Signature Issues&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Method</th><th>Current Return Type</th><th>Required Return Type</th><th>Impact</th></tr></thead><tbody><tr><td><code>getDownloadsFile</code></td><td><code>Promise&lt;unknown&gt;</code></td><td><code>Promise&lt;ArrayBuffer&gt;</code></td><td>No type safety for binary download</td></tr></tbody></table><h3 id="orphan-types" tabindex="-1">Orphan Types <a class="header-anchor" href="#orphan-types" aria-label="Permalink to &quot;Orphan Types&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type Name</th><th>Status</th><th>Action</th></tr></thead><tbody><tr><td><code>ResponseError</code></td><td>Not in swagger</td><td>Remove or document rationale</td></tr></tbody></table><h3 id="deprecated-v2-types-must-preserve" tabindex="-1">Deprecated v2 Types (Must Preserve) <a class="header-anchor" href="#deprecated-v2-types-must-preserve" aria-label="Permalink to &quot;Deprecated v2 Types (Must Preserve)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type Name</th><th>Status</th><th>Action</th></tr></thead><tbody><tr><td><code>NmReportDetailRequest</code></td><td>Deprecated</td><td>Retain with <code>@deprecated</code> tag</td></tr><tr><td><code>NmReportDetailResponse</code></td><td>Deprecated</td><td>Retain with <code>@deprecated</code> tag</td></tr><tr><td><code>NmReportDetail*</code> (6 types total)</td><td>Deprecated</td><td>Retain with <code>@deprecated</code> tags, do NOT remove</td></tr></tbody></table><hr><h2 id="implementation-approach" tabindex="-1">Implementation Approach <a class="header-anchor" href="#implementation-approach" aria-label="Permalink to &quot;Implementation Approach&quot;">​</a></h2><h3 id="step-1-fix-availabilityfilters-type" tabindex="-1">Step 1: Fix AvailabilityFilters Type <a class="header-anchor" href="#step-1-fix-availabilityfilters-type" aria-label="Permalink to &quot;Step 1: Fix AvailabilityFilters Type&quot;">​</a></h3><p>Change the type from the malformed union <code>&#39;deficient&#39; | &#39;actual&#39; | ... | &#39;invalidData&#39;[]</code> to the correctly parenthesized array type <code>(&#39;deficient&#39; | &#39;actual&#39; | &#39;balanced&#39; | &#39;nonActual&#39; | &#39;nonLiquid&#39; | &#39;invalidData&#39;)[]</code>. This ensures the entire union is the element type of the array, matching the swagger <code>type: array, items: { type: string, enum: [...] }</code> definition.</p><h3 id="step-2-populate-tableproductitem-interface" tabindex="-1">Step 2: Populate TableProductItem Interface <a class="header-anchor" href="#step-2-populate-tableproductitem-interface" aria-label="Permalink to &quot;Step 2: Populate TableProductItem Interface&quot;">​</a></h3><p>Replace the empty interface with all 18+ fields from the swagger <code>allOf</code> structure: <code>nmId</code>, <code>name</code>, <code>vendorCode</code>, <code>subjectName</code>, <code>brandName</code>, <code>mainPhoto</code>, <code>isAdvertised</code>, <code>isSubstitutedSKU</code>, <code>isCardRated</code>, <code>rating</code>, <code>feedbackRating</code>, <code>price</code>, <code>avgPosition</code>, <code>openCard</code>, <code>addToCart</code>, <code>openToCart</code>, <code>orders</code>, <code>cartToOrder</code>, <code>visibility</code>.</p><h3 id="step-3-add-errorobject-type" tabindex="-1">Step 3: Add ErrorObject Type <a class="header-anchor" href="#step-3-add-errorobject-type" aria-label="Permalink to &quot;Step 3: Add ErrorObject Type&quot;">​</a></h3><p>Add the <code>ErrorObject</code> interface to <code>analytics.types.ts</code> with <code>code</code> (number) and <code>message</code> (string) fields based on the v3 error response schema.</p><h3 id="step-4-add-orderbymainanddetails-schema" tabindex="-1">Step 4: Add OrderByMainAndDetails Schema <a class="header-anchor" href="#step-4-add-orderbymainanddetails-schema" aria-label="Permalink to &quot;Step 4: Add OrderByMainAndDetails Schema&quot;">​</a></h3><p>Either rename the generic <code>OrderBy</code> type to <code>OrderByMainAndDetails</code> or add a type alias so the SDK type name matches the swagger schema name.</p><h3 id="step-5-fix-getdownloadsfile-return-type" tabindex="-1">Step 5: Fix getDownloadsFile Return Type <a class="header-anchor" href="#step-5-fix-getdownloadsfile-return-type" aria-label="Permalink to &quot;Step 5: Fix getDownloadsFile Return Type&quot;">​</a></h3><p>Change the return type from <code>Promise&lt;unknown&gt;</code> to <code>Promise&lt;ArrayBuffer&gt;</code> in <code>src/modules/analytics/index.ts</code> to match the swagger <code>application/zip</code> binary response specification.</p><h3 id="step-6-clean-up-responseerror-orphan-type" tabindex="-1">Step 6: Clean Up ResponseError Orphan Type <a class="header-anchor" href="#step-6-clean-up-responseerror-orphan-type" aria-label="Permalink to &quot;Step 6: Clean Up ResponseError Orphan Type&quot;">​</a></h3><p>Remove the <code>ResponseError</code> type that has no corresponding swagger schema, or if it serves an internal purpose, add documentation explaining why it exists.</p><h3 id="step-7-verify-backward-compatibility" tabindex="-1">Step 7: Verify Backward Compatibility <a class="header-anchor" href="#step-7-verify-backward-compatibility" aria-label="Permalink to &quot;Step 7: Verify Backward Compatibility&quot;">​</a></h3><p>Confirm that all 6 deprecated v2 types (<code>NmReportDetail*Request/Response</code> variants) retain their <code>@deprecated</code> tags and are NOT removed.</p><h3 id="step-8-validate-type-safety" tabindex="-1">Step 8: Validate Type Safety <a class="header-anchor" href="#step-8-validate-type-safety" aria-label="Permalink to &quot;Step 8: Validate Type Safety&quot;">​</a></h3><p>Run <code>npx tsc --noEmit</code> to ensure zero TypeScript errors in strict mode across the entire project.</p><hr><h2 id="files-to-modify" tabindex="-1">Files to Modify <a class="header-anchor" href="#files-to-modify" aria-label="Permalink to &quot;Files to Modify&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Changes</th><th>Estimated Effort</th></tr></thead><tbody><tr><td><code>src/types/analytics.types.ts</code></td><td>Fix AvailabilityFilters, populate TableProductItem, add ErrorObject, add OrderByMainAndDetails, remove/document ResponseError, preserve deprecated types</td><td>High</td></tr><tr><td><code>src/modules/analytics/index.ts</code></td><td>Fix getDownloadsFile return type</td><td>Low</td></tr></tbody></table><hr><h2 id="success-criteria" tabindex="-1">Success Criteria <a class="header-anchor" href="#success-criteria" aria-label="Permalink to &quot;Success Criteria&quot;">​</a></h2><ul><li>[ ] AvailabilityFilters type fixed from malformed union to proper array type: <code>(&#39;deficient&#39; | &#39;actual&#39; | ... | &#39;invalidData&#39;)[]</code></li><li>[ ] TableProductItem interface populated with all 18+ fields from swagger (nmId, name, vendorCode, subjectName, brandName, mainPhoto, isAdvertised, isSubstitutedSKU, isCardRated, rating, feedbackRating, price, avgPosition, openCard, addToCart, openToCart, orders, cartToOrder, visibility)</li><li>[ ] ErrorObject type added for v3 endpoint error responses (code, message fields)</li><li>[ ] OrderByMainAndDetails schema represented in SDK types (either rename or add alias)</li><li>[ ] getDownloadsFile return type changed from <code>Promise&lt;unknown&gt;</code> to <code>Promise&lt;ArrayBuffer&gt;</code> or appropriate binary type</li><li>[ ] 6 deprecated v2 types (NmReportDetail*Request/Response) retain <code>@deprecated</code> tags and are NOT removed for backward compatibility</li><li>[ ] ResponseError orphan type either removed or documented with rationale</li><li>[ ] All type changes pass TypeScript strict compilation with zero errors</li></ul><hr><h2 id="risk-assessment" tabindex="-1">Risk Assessment <a class="header-anchor" href="#risk-assessment" aria-label="Permalink to &quot;Risk Assessment&quot;">​</a></h2><p><strong>Risk Level: MEDIUM</strong></p><ul><li><strong>AvailabilityFilters fix is a BREAKING CHANGE</strong>: Any code passing a bare string where the corrected array type is expected will fail to compile. This is intentional — the old type was incorrect and did not match the API contract.</li><li><strong>TableProductItem population is technically breaking</strong>: Any code relying on the empty interface (e.g., casting to <code>any</code> or using index signatures) may need adjustment. However, adding fields to a previously empty interface is additive in practice.</li><li><strong>getDownloadsFile return type change is breaking</strong>: Code using <code>Promise&lt;unknown&gt;</code> may need type adjustments, but this fix provides correct type information for binary responses.</li><li><strong>Removing ResponseError is breaking if imported</strong>: Any consumer importing this orphan type will break. If removal is too risky, document it instead.</li><li><strong>Adding new types is non-breaking</strong>: <code>ErrorObject</code> and <code>OrderByMainAndDetails</code> are additive changes.</li><li><strong>Preserving deprecated types is non-breaking</strong>: No removal, only annotation.</li></ul><hr><h2 id="dependencies" tabindex="-1">Dependencies <a class="header-anchor" href="#dependencies" aria-label="Permalink to &quot;Dependencies&quot;">​</a></h2><ul><li><strong>Depends on</strong>: None (standalone type fixes)</li><li><strong>Blocks</strong>: task-42 (Analytics Code Quality — JSDoc, Rate Limits, Tests, Config Cleanup)</li></ul><hr><h2 id="related-documents" tabindex="-1">Related Documents <a class="header-anchor" href="#related-documents" aria-label="Permalink to &quot;Related Documents&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Document</th><th>Path</th></tr></thead><tbody><tr><td>Swagger spec</td><td><code>wildberries_api_doc/11-analytics.yaml</code></td></tr><tr><td>Swagger shards</td><td><code>wildberries_api_doc/11-analytics/</code> (4 shards)</td></tr><tr><td>Deprecated v2 spec</td><td><code>wildberries_api_doc/11-analytics.v2-deprecated.yaml</code></td></tr><tr><td>Module source</td><td><code>src/modules/analytics/index.ts</code> (533 lines)</td></tr><tr><td>Types file</td><td><code>src/types/analytics.types.ts</code> (1901 lines)</td></tr><tr><td>Rate limits config</td><td><code>src/config/analytics-rate-limits.ts</code> (97 lines)</td></tr><tr><td>Unit tests</td><td><code>tests/unit/modules/analytics-v3-methods.test.ts</code> (659 lines)</td></tr><tr><td>Story 3.3</td><td><code>docs/stories/3.3.analytics-sales-statistics.md</code></td></tr><tr><td>Story 3.4</td><td><code>docs/stories/3.4.analytics-stock-csv-reports.md</code></td></tr><tr><td>Story 4.3</td><td><code>docs/stories/4.3.analytics-sales-statistics.md</code></td></tr><tr><td>QA Gate 3.3</td><td><code>docs/qa/gates/3.3-analytics-sales-statistics.yml</code></td></tr><tr><td>QA Gate 3.4</td><td><code>docs/qa/gates/3.4-analytics-stock-csv-reports.yml</code></td></tr><tr><td>QA Gate 4.3</td><td><code>docs/qa/gates/4.3-analytics-sales-statistics.yml</code></td></tr><tr><td>EPIC 42 (code quality)</td><td><code>docs/epics/EPIC_42_ANALYTICS_CODE_QUALITY.md</code></td></tr><tr><td>Backlog task</td><td><code>backlog/tasks/task-41</code></td></tr></tbody></table>',61)])])}const y=t(o,[["render",i]]);export{u as __pageData,y as default};
